mapper.select:
SELECT t.transaction_id AS transactionId, t.parent_transaction_id AS parentTransactionId, t.user_id AS userId, t.receive_id AS receiveId, t.settlement_id AS settlementId, t.transaction_type AS transactionType, t.source_type AS sourceType, t.target_type AS targetType, t.transaction_status AS transactionStatus, t.amount, t.merchant_name AS merchantName, t.spending_category_id AS spendingCategoryId, t.created_at AS createdAt, m.memo_content AS memo, COALESCE(p_rec.nickname, u_rec.user_name, t.merchant_name) AS receiverName, COALESCE(p_send.nickname, u_send.user_name) AS senderName FROM financial_transaction_tbl t LEFT JOIN receipt_memo_tbl m ON t.transaction_id = m.transaction_id LEFT JOIN user_tbl u_rec ON t.receive_id = u_rec.user_id LEFT JOIN profile_tbl p_rec ON u_rec.user_id = p_rec.user_id LEFT JOIN user_tbl u_send ON t.user_id = u_send.user_id LEFT JOIN profile_tbl p_send ON u_send.user_id = p_send.user_id WHERE (t.user_id = #{userId} OR t.receive_id = #{userId})
AND t.transaction_type = #{type}
ORDER BY t.transaction_id DESC

mapper.update:
UPDATE receipt_memo_tbl
SET memo_content = #{memo}, updated_at = NOW()
WHERE transaction_id = #{transactionId}
